import{_ as t,o as a,c as r,a5 as s}from"./chunks/framework.CslsFoWx.js";const p=JSON.parse('{"title":"Synthèse commerciale","description":"","frontmatter":{},"headers":[],"relativePath":"commercial/index.md","filePath":"commercial/index.md","lastUpdated":1794431647000}'),i={name:"commercial/index.md"};function n(o,e,d,l,c,u){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="synthese-commerciale" tabindex="-1">Synthèse commerciale <a class="header-anchor" href="#synthese-commerciale" aria-label="Permalink to &quot;Synthèse commerciale&quot;">​</a></h1><blockquote><p>Sources : <a href="/VendoraSystem-docs/commercial/etude-concurrentielle">étude concurrentielle du 25/10/2026</a> (benchmark de 17 acteurs, vérification contradictoire des affirmations clés) et <a href="/VendoraSystem-docs/commercial/actions-terrain">plan d&#39;actions terrain du 28/10/2026</a>. Les fourchettes de prix sont des <strong>recommandations</strong> déduites des prix publics observés, pas des décisions.</p></blockquote><h2 id="modele-economique-11-11-2026-proposition-a-valider" tabindex="-1">Modèle économique (11/11/2026, proposition à valider) <a class="header-anchor" href="#modele-economique-11-11-2026-proposition-a-valider" aria-label="Permalink to &quot;Modèle économique (11/11/2026, proposition à valider)&quot;">​</a></h2><ul><li><a href="/VendoraSystem-docs/commercial/modele-economique"><strong>Modèle économique</strong></a> : formule <strong>Gratuit</strong> (1 magasin, 1 appareil) + Commerce 39 DT / 29 € et Restaurant 69 DT / 59 €, options, <strong>assistant IA avec 3 mois offerts</strong>, <strong>API avec quota gratuit puis paiement à l&#39;usage</strong> (packs prépayés en Tunisie, plafond de dépense en France), services, offres de lancement et points de vigilance.</li></ul><h2 id="etudes-05-11-2026" tabindex="-1">Études (05/11/2026) <a class="header-anchor" href="#etudes-05-11-2026" aria-label="Permalink to &quot;Études (05/11/2026)&quot;">​</a></h2><ul><li><a href="/VendoraSystem-docs/commercial/plan-commercialisation"><strong>Plan de commercialisation par Internet, prix et abonnements</strong></a> : canaux en ligne (publicité, SEO, comparateurs, réseaux, partenariats), prospection directe des restaurants et commerces (séquences, scripts, objections), révision des formules et des prix, <strong>essai gratuit de 2 mois sans carte</strong> (appliqué le 05/11/2026 : 60 jours par défaut), tunnel de vente du site, plan 90 jours et 12 mois, budget et KPI.</li><li><a href="/VendoraSystem-docs/commercial/etude-commerciale"><strong>Étude commerciale et positionnement</strong></a> : comment vendre Vendora, grilles de prix recommandées par marché (Tunisie en dinars, France en euros), segments et personas, canaux, marketing, plan à 12 mois et décisions à prendre.</li><li><a href="/VendoraSystem-docs/commercial/etude-gaas"><strong>Étude GaaS — Agent as a Service</strong></a> : comment le SaaS peut évoluer vers des agents IA opérant pour le commerçant (réassort, anti-fraude, clôtures, prix), option retenue, architecture, droit des données, packaging et prix, feuille de route.</li></ul><h2 id="proposition-de-valeur" tabindex="-1">Proposition de valeur <a class="header-anchor" href="#proposition-de-valeur" aria-label="Permalink to &quot;Proposition de valeur&quot;">​</a></h2><p><strong>Une caisse qui ne s&#39;arrête jamais, pour tous les commerces, sur le matériel qu&#39;on a déjà, conforme au fisc local, sans engagement.</strong></p><table tabindex="0"><thead><tr><th>Promesse</th><th>Ce qui la rend vraie aujourd&#39;hui</th><th>État</th></tr></thead><tbody><tr><td><strong>Offline réel multi-appareils</strong> — caisse, téléphones de salle, cuisine continuent de se parler sans internet</td><td>Outbox + synchronisation idempotente, <strong>hub local</strong> (élection, relais temps réel, rattrapage), clé LAN + identité Ed25519 par appareil</td><td><span class="badge ok">Fait</span> prouvé émulateur + simulateur ; validation 3 appareils physiques à faire</td></tr><tr><td><strong>Multi-commerces</strong> — épicerie, boutique, restaurant, services</td><td>Cœur commun + modules ; restaurant complet ; clients, fidélité, ardoise, fournisseurs et inventaires livrés</td><td><span class="badge partial">Partiel</span> variantes, vente au poids, péremption et services en phase 4 ; multi-magasins en phase 3</td></tr><tr><td><strong>Android et iOS</strong> — pas d&#39;iPad imposé</td><td>Deux apps natives au même niveau à chaque lot, moteur partagé</td><td><span class="badge ok">Fait</span></td></tr><tr><td><strong>Rapide</strong> — moins de 100 ms par action</td><td>Mesure in-app + banc 50 000 produits, télémétrie remontée au back-office</td><td><span class="badge ok">Fait</span> mesure tablette d&#39;entrée de gamme à faire</td></tr><tr><td><strong>Anti-fraude</strong> — rien ne se réécrit</td><td>Ventes scellées et chaînées, Z infalsifiable, PIN manager tracé, alertes d&#39;intégrité, alertes anti-fraude (annulations, remises, tiroirs, écarts) et stock bas notifiées aux responsables</td><td><span class="badge ok">Fait</span></td></tr><tr><td><strong>Conforme</strong></td><td>France : chaînage, clôtures J/M/A, archive, mode formation, attestation. Tunisie : NACEF</td><td><span class="badge partial">Partiel</span> NACEF bloqué par le cahier des charges ; certification NF525 à engager</td></tr><tr><td><strong>White-label</strong></td><td>Thème magasin / marque, logo, langue fr / en / ar avec RTL, configuration par appareil</td><td><span class="badge ok">Fait</span> branding kiosque complet phase 4</td></tr><tr><td><strong>Fidélisation</strong> — clients, points, ardoise, reçu digital</td><td>Fiches clients, fidélité par points et paliers, ardoise plafonnée, reçu par email</td><td><span class="badge ok">Fait</span> SMS / WhatsApp à brancher</td></tr><tr><td><strong>SaaS prêt à vendre</strong> — formules, limites, facturation</td><td>Console Vendora : clients, formules appliquées par le serveur, cycle de vie sans couper la vente, factures et devis ; tarifs publics lus dans la console</td><td><span class="badge ok">Fait</span> informations de la société et emails réels à renseigner</td></tr><tr><td><strong>Paiements locaux</strong></td><td>Couche fournisseur pluggable, QR Flouci / Konnect simulés, webhooks signés, rapprochement</td><td><span class="badge blocked">Bloqué (terrain)</span> passerelles réelles = comptes marchands</td></tr></tbody></table><h2 id="marches-cibles" tabindex="-1">Marchés cibles <a class="header-anchor" href="#marches-cibles" aria-label="Permalink to &quot;Marchés cibles&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Tunisie</th><th>France</th></tr></thead><tbody><tr><td><strong>Déclencheur</strong></td><td>Caisse homologuée <strong>NACEF obligatoire</strong> par vagues 2025 → 2028 (personnes morales depuis le 01/07/2026)</td><td>Art. 286 CGI (inaltérabilité, NF525) + <strong>e-reporting B2C</strong> 2026-2027</td></tr><tr><td><strong>Concurrence</strong></td><td>Wasel, Kesti, Al-Makhzan — tous F&amp;B, tous « offline » mono-poste, aucune homologation vérifiable</td><td>Square, SumUp, Zettle (0 €/mois + commission) ; Zelty, L&#39;Addition, Cashpad, Lightspeed (CHR, souvent iPad-only, sur devis)</td></tr><tr><td><strong>Ancrage prix</strong></td><td>29 → 79 TND/mois, licence 199-599 DT</td><td>0 € + 1,65-1,75 % ; 49 → 249 €/mois</td></tr><tr><td><strong>Paiements</strong></td><td>Cash dominant (bancarisation ~38 %), ardoise courante ; Flouci, Konnect, Paymee ; TUNPAY à venir</td><td>CB, titres-restaurant (Conecs), pourboires défiscalisés</td></tr><tr><td><strong>Notre angle</strong></td><td>Degré d&#39;offline (multi-appareils), multi-vertical, homologation précoce, anti-fraude, ardoise tracée</td><td>Offline documenté publiquement, Android + iOS, white-label, prix public sans engagement, NF525 affichée</td></tr></tbody></table><p>Détail : <a href="/VendoraSystem-docs/commercial/marches">marchés et réglementation</a>.</p><h2 id="positionnement-prix-recommande" tabindex="-1">Positionnement prix recommandé <a class="header-anchor" href="#positionnement-prix-recommande" aria-label="Permalink to &quot;Positionnement prix recommandé&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Offre</th><th>Tunisie</th><th>France</th></tr></thead><tbody><tr><td><strong>Prix publiés (Console Vendora)</strong></td><td>Essentiel 29 €, Commerce 49 €, Restaurant 79 € HT / mois, Sur mesure ; +9 € par appareil ; annuel = 2 mois offerts ; <strong>essai gratuit de 2 mois sans carte</strong> (60 jours depuis le 05/11/2026) — page publique à jour automatiquement</td><td>idem, en euros</td></tr><tr><td><strong>Entrée</strong> — 1 caisse, 1 magasin</td><td>35 – 49 TND / mois</td><td>39 – 59 € / mois</td></tr><tr><td><strong>Pro / restaurant complet</strong> — caisse + téléphones de salle + KDS</td><td>69 – 89 TND / mois</td><td>79 – 129 € / mois</td></tr><tr><td><strong>Options</strong></td><td>Multi-magasins, kiosque, white-label, module NACEF homologué</td><td>Multi-magasins, white-label</td></tr><tr><td><strong>Principes</strong></td><td>Annuel = 2 mois offerts, <strong>0 % de commission</strong></td><td>Grille publique, <strong>sans engagement</strong>, appareils secondaires inclus</td></tr></tbody></table><h2 id="differenciateurs-a-mettre-en-avant-en-demo" tabindex="-1">Différenciateurs à mettre en avant en démo <a class="header-anchor" href="#differenciateurs-a-mettre-en-avant-en-demo" aria-label="Permalink to &quot;Différenciateurs à mettre en avant en démo&quot;">​</a></h2><ol><li><strong>« Box débranchée en plein rush »</strong> : la caisse, les téléphones et la cuisine continuent ; le retour d&#39;internet resynchronise tout sans doublon.</li><li><strong>Une seule app pour tous les rôles</strong> : le même téléphone devient caisse, téléphone de salle ou écran cuisine selon son appairage.</li><li><strong>Rien ne se réécrit</strong> : annulation sous PIN manager, Z chaîné, alertes d&#39;intégrité au tableau de bord.</li><li><strong>Le magasin à son image</strong> : couleurs, logo, langue arabe en RTL, configuration par appareil, publiés sans redémarrer.</li><li><strong>Paiement par QR</strong> à la caisse et à la table, rapproché automatiquement au back-office.</li></ol><h2 id="ce-qui-bloque-la-commercialisation" tabindex="-1">Ce qui bloque la commercialisation <a class="header-anchor" href="#ce-qui-bloque-la-commercialisation" aria-label="Permalink to &quot;Ce qui bloque la commercialisation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sujet</th><th>Action</th><th>Responsable</th></tr></thead><tbody><tr><td>Homologation NACEF (Tunisie, restauration)</td><td>Récupérer le cahier des charges depuis une connexion tunisienne, appeler la DGI, réviser la spec 15</td><td>Terrain</td></tr><tr><td>Paiements réels</td><td>Comptes sandbox Konnect / Paymee, partenariat API QR Flouci</td><td>Terrain</td></tr><tr><td>Certification NF525 / LNE (France)</td><td>Choisir attestation éditeur puis certification, verrouiller la politique de version</td><td>Terrain + produit</td></tr><tr><td>E-reporting B2C (France)</td><td>Présélectionner une plateforme agréée API-first en marque blanche</td><td>Terrain, phase 3</td></tr><tr><td>Matériel</td><td>Valider douchette, imprimante, tiroir, hub à 3 appareils</td><td><a href="/VendoraSystem-docs/tests/validation-materiel">Validation matériel</a></td></tr><tr><td>Entité juridique, hébergement, fournisseur d&#39;emails</td><td>Saisir l&#39;identité de la société et la TVA dans la Console (validation comptable), choisir le fournisseur SMTP, héberger l&#39;API (<a href="/VendoraSystem-docs/applications/console">liste dans la console</a>)</td><td>Direction</td></tr></tbody></table><p>Voir aussi : <a href="/VendoraSystem-docs/commercial/legal">textes légaux tunisiens</a> · <a href="/VendoraSystem-docs/suivi/#risques">risques</a>.</p>',19)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
